"""Assemble the Vietnamese final report strictly from recorded evidence."""
from pathlib import Path
import csv,json
p=Path('reports/BAO_CAO_LAB21.md');base=p.read_text().split('<!-- RESULTS -->')[0]
base=base.replace('Báo cáo đang được xây dựng từ thực nghiệm thật. Chưa công bố cấu hình cuối cùng hoặc điểm số trước khi hoàn thành kiểm tra tương ứng. Dữ liệu synthetic chỉ được dùng trong regression tests.','Đã chạy thực nghiệm trên dữ liệu thật, xuất đủ năm sequence và tính TrackEval cho video_1. Dữ liệu synthetic chỉ được dùng trong regression tests, không đưa vào kết quả lab.')
env=json.loads(Path('artifacts/environment.json').read_text());data=json.loads(Path('artifacts/scene_analysis/dataset_metadata.json').read_text());configs=json.loads(Path('reports/selected_configs.json').read_text());candidates=json.loads(Path('artifacts/metrics/video_1_candidates.json').read_text())
